        {
            code: "var foo = [1,(\n2\n), 3];",
            output: "var foo = [1,\n(\n2\n),\n3];",
            options: ["always"],
            errors: [
                {
                    messageId: "missingLineBreak",
                    line: 1,
                    column: 14
                },
                {
                    messageId: "missingLineBreak",
                    line: 3,
                    column: 3
                }
            ]
        },
        {
            code: "var foo = [1,        \t      (\n2\n),\n3];",
            output: "var foo = [1,\n(\n2\n),\n3];",
            options: ["always"],
            errors: [
                {
